  brick: new Color("#a27e65"),
  plaster: new Color("#c9bea7"),
  tile: new Color("#a4664b"),
  foliage: new Color("#3a5a34"),
  timber: new Color("#5a3c24"),
  stone: new Color("#b5aa93"),
  void: new Color("#1c1612")
